const c = $('Case Input').item.json;
const prohibited = typeof c.prohibited_tools === 'string' ? JSON.parse(c.prohibited_tools || '[]') : (c.prohibited_tools || []);
const contextMessages = typeof c.context_messages === 'string' ? JSON.parse(c.context_messages || '[]') : (c.context_messages || []);
const d = $json || {};
const answer = (d.output ?? d.text ?? d.response ?? '').toString();
const steps = Array.isArray(d.intermediateSteps) ? d.intermediateSteps : [];
const tools = [...new Set(steps.map((s) => s && s.action && s.action.tool).filter(Boolean))];
const prohibited_used = prohibited.filter((t) => tools.includes(t));
const quoteMatches = [...answer.matchAll(/"([^"\n]{12,180})"/g)].map((m) => m[1].trim());
const quotes = [...new Set(quoteMatches)].filter((s) => !/https?:|\]\(|netlify/.test(s));
const hasHeading = /^\s{0,3}#{1,6}\s/m.test(answer);
const hasBlockquote = /^\s*>\s/m.test(answer);
const rawUrls = answer.match(/(?<!\]\()https?:\/\/[^\s)]+/g) || [];
const format_flags = { env: c.env, has_markdown_heading: hasHeading, has_blockquote: hasBlockquote, raw_url_count: rawUrls.length };
const citations = [];
const linkRe = /\[([0-9:]+)\]\(https?:\/\/pidgeonhead\.netlify\.app\/sessions\/([0-9a-fA-F-]{36})\?t=([0-9.]+)\)/g;
let lm;
while ((lm = linkRe.exec(answer)) !== null) {
  const before = answer.slice(0, lm.index);
  const qm = [...before.matchAll(/"([^"\n]{6,200})"/g)].pop();
  citations.push({ quote: qm ? qm[1].trim() : '', session_id: lm[2], cited_seconds: parseFloat(lm[3]) });
}
const cited_session_ids = [...new Set(citations.map((x) => x.session_id))];
const vq_payload = JSON.stringify({ quotes, sids: cited_session_ids });
return { json: {
  run_id: c.run_id, run_date: c.run_date, env: c.env, case_id: c.case_id,
  question: c.input, answer, tools_used: tools, prohibited_used,
  quotes, citations, cited_session_ids, vq_payload, format_flags, ground_truth: c.ground_truth, rubric: c.rubric,
} };

