const e = $('Extract & Check').item.json;
const vq = $('Verify Quotes').item.json || {};
const qc = vq.quote_checks || [];
const transcripts = vq.transcripts || {};
const raw = ($json.text ?? $json.output ?? $json.response ?? '').toString();
let j = {};
try { const m = raw.match(/\{[\s\S]*\}/); j = JSON.parse(m ? m[0] : raw); } catch (err) { j = {}; }
const scores = j.scores || (j.output && j.output.scores) || {};
const just = j.justifications || (j.output && j.output.justifications) || {};
let verdict = j.overall_verdict || (j.output && j.output.overall_verdict) || 'unknown';
function normWords(str){ return String(str).split(/\s+/).map((t) => t.toLowerCase().replace(/[^a-z0-9]/g, '')).filter(Boolean); }
function locate(words, starts, quote){ const qw = normWords(quote); if (!qw.length) return null; const k = Math.min(qw.length, 6); for (let i = 0; i + k <= words.length; i++) { let ok = true; for (let x = 0; x < k; x++) { if (words[i + x] !== qw[x]) { ok = false; break; } } if (ok) return Number(starts[i]); } return null; }
const TOL = 8;
const timestamp_checks = (e.citations || []).map((c) => {
  const tx = transcripts[c.session_id];
  const actual = (tx && Array.isArray(tx.words)) ? locate(tx.words, tx.starts, c.quote) : null;
  const matched = actual != null;
  const delta = matched ? Math.round(Math.abs(actual - c.cited_seconds)) : null;
  return { quote: c.quote, session_id: c.session_id, cited: c.cited_seconds, actual: matched ? Math.round(actual) : null, delta, ok: matched && delta <= TOL };
});
if (timestamp_checks.length) {
  const good = timestamp_checks.filter((t) => t.ok).length;
  scores.citation_validity = Math.max(1, Math.round((5 * good) / timestamp_checks.length));
  just.citation_validity = good + '/' + timestamp_checks.length + ' cited timestamps matched within ' + TOL + 's (deterministic, no judge)';
}
const fabricated = (Array.isArray(qc) ? qc : []).filter((x) => x && x.found === false).map((x) => x.quote);
if ((e.prohibited_used || []).length) verdict = 'fail';
const tsOff = timestamp_checks.filter((t) => !t.ok).length;
const deterministic = { prohibited_tools_used: e.prohibited_used, unverified_quotes: fabricated, timestamp_checks, format: e.format_flags };
const row = { run_id: e.run_id, run_date: e.run_date, case_id: e.case_id, env: e.env, question: e.question, answer: e.answer, tools_used: e.tools_used || [], prohibited_tools_used: e.prohibited_used || [], scores, overall_verdict: verdict, quote_checks: qc, deterministic_checks: deterministic, judge_rationale: just };
return { json: { row, scorecard: { case_id: e.case_id, verdict, scores, unverified_quotes: fabricated, prohibited_tools_used: e.prohibited_used || [], timestamps: { total: timestamp_checks.length, ok: timestamp_checks.length - tsOff, off: tsOff }, format_flags: e.format_flags } } };

const row = $json.row || {};
const sc = $json.scorecard || {};
const scores = row.scores || {};
const caseId = row.case_id || sc.case_id || '';
const runId = row.run_id || '';
const tools = Array.isArray(row.tools_used) ? row.tools_used.join(', ') : '';
const verdict = row.overall_verdict || sc.verdict || 'unknown';
const s = (v) => (v === undefined || v === null) ? '' : String(v);
return { json: {
  result_id: $execution.id + '-' + caseId,
  run_id: runId,
  case_id: caseId,
  response: row.answer || '',
  tools_called: tools,
  faithfulness: s(scores.faithfulness),
  citation_validity: s(scores.citation_validity),
  source_routing: s(scores.source_routing),
  completeness: s(scores.completeness),
  relevance: s(scores.relevance),
  format: s(scores.format),
  verdict: verdict,
  run_date: new Date().toISOString()
} };
